function comicProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:8;
  var edge=opts.edge!=null?opts.edge:28;
  if(cell<3)cell=3; else if(cell>24)cell=24;
  if(edge<0)edge=0; else if(edge>128)edge=128;
  var lum=new Float32Array(w*h);
  for(var i=0,y=0;y<h;y++) for(var x=0;x<w;x++,i++){ var p=(y*w+x)*4; lum[y*w+x]=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  function L(x,y){ if(x<0)x=0; else if(x>w-1)x=w-1; if(y<0)y=0; else if(y>h-1)y=h-1; return lum[y*w+x]; }
  var out=new Uint8ClampedArray(data.length);
  for(var i2=0;i2<out.length;i2+=4){ out[i2]=255; out[i2+1]=255; out[i2+2]=255; out[i2+3]=255; }
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var gx=L(x-1,y-1)+2*L(x-1,y)+L(x-1,y+1)-L(x+1,y-1)-2*L(x+1,y)-L(x+1,y+1);
    var gy=L(x-1,y-1)+2*L(x,y-1)+L(x+1,y-1)-L(x-1,y+1)-2*L(x,y+1)-L(x+1,y+1);
    if(Math.sqrt(gx*gx+gy*gy)>edge){ var p=(y*w+x)*4; out[p]=0; out[p+1]=0; out[p+2]=0; }
  }
  var cc=cell/2;
  for(var gy2=0;gy2<h;gy2+=cell) for(var gx2=0;gx2<w;gx2+=cell){
    var px=gx2+cc, py=gy2+cc;
    if(px>=w||py>=h) continue;
    var l=lum[Math.floor(py)*w+Math.floor(px)];
    var rad=(1-l/255)*cell*0.6;
    if(rad<0.5) continue;
    var x0=Math.max(0,Math.floor(px-rad)), x1=Math.min(w-1,Math.ceil(px+rad));
    var y0=Math.max(0,Math.floor(py-rad)), y1=Math.min(h-1,Math.ceil(py+rad));
    for(var yy=y0;yy<=y1;yy++) for(var xx=x0;xx<=x1;xx++){
      var ddx=xx-px, ddy=yy-py;
      if(ddx*ddx+ddy*ddy<=rad*rad){ var pp=(yy*w+xx)*4; if(out[pp]!==0||out[pp+1]!==0||out[pp+2]!==0){ out[pp]=0; out[pp+1]=0; out[pp+2]=0; } }
    }
  }
  return out;
}

var EXPORTS={comicProcess:comicProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ComicForgePure = EXPORTS; }
